export default function ({ app, router, store, Vue }) {

  // El interceptor de F2. Idéntico.
  apiClient.interceptors.request.use(function (config) {
    const token = store.state.auth.token
    if (token) {
      config.headers.Authorization = 'Bearer ' + token
    }
