      if (error.response && error.response.status === 401) {
        store.dispatch('auth/logout')
        router.push('/login')
      }
      return Promise.reject(error)
    }
  )

  // Lo que en el curso base era Vue.prototype.$api
  Vue.prototype.$api = apiClient
}

