  if (!token) return res.status(401).json({ error: "Token ausente" });
  try {
    req.user = verify(token);   // { sub, role, name } — la fuente de verdad del backend
    next();
  } catch (err) {
    return res.status(401).json({ error: "Token inválido o expirado" });
  }
};

